// GetCountByCustomerIdAndStatus retrieves the atomic count of CustomerInvoice records grouped by CustomerIdAndStatus.
func (r *customerinvoiceRepository) GetCountByCustomerIdAndStatus(ctx context.Context, tx fdblayer.ReadTx, CustomerId string, Status OrderStatus) (int64, error) {
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	tr := tx.ReadTransaction()
	dir := tx.Dir()
	val := tr.Get(dir.Pack(tuple.Tuple{CustomerInvoiceTypeID, fdblayer.AggregateNamespace, 2, CustomerId, int64(Status)})).MustGet()
	if len(val) < 8 {
		return 0, nil
	}
	return int64(binary.LittleEndian.Uint64(val)), nil
}

