// GetMinAmountCentsByCustomerId retrieves the atomic minimum of AmountCents grouped by CustomerId.
func (r *customerinvoiceRepository) GetMinAmountCentsByCustomerId(ctx context.Context, tx fdblayer.ReadTx, CustomerId string) (int64, bool, error) {
	if err := ctx.Err(); err != nil {
		return 0, false, err
	}
	tr := tx.ReadTransaction()
	dir := tx.Dir()
	val := tr.Get(dir.Pack(tuple.Tuple{CustomerInvoiceTypeID, fdblayer.AggregateNamespace, 4, CustomerId})).MustGet()
	if len(val) < 8 {
		return 0, false, nil
	}
	return int64(binary.LittleEndian.Uint64(val) ^ (1 << 63)), true, nil
}

